def tr_lower(s):
    """
    Türkçe kurallarına göre küçük harfe çevirir.
    I -> ı, İ -> i gibi özel durumlar içerir.
    """
    # Türkçe harf dönüştürme eşlemesi (büyükten küçüğe)
    turkce_buyuk_kucuk = {
        'I': 'ı',
        'İ': 'i'
    }

    result = ""
    for char in s:
        if char in turkce_buyuk_kucuk:
            result += turkce_buyuk_kucuk[char]
        else:
            result += char.lower()
    return result


def tr_upper(s):
    """
    Türkçe kurallarına göre büyük harfe çevirir.
    ı -> I, i -> İ gibi özel durumlar içerir.
    """
    # Türkçe harf dönüştürme eşlemesi (küçükten büyüğe)
    turkce_kucuk_buyuk = {
        'ı': 'I',
        'i': 'İ'
    }

    result = ""
    for char in s:
        if char in turkce_kucuk_buyuk:
            result += turkce_kucuk_buyuk[char]
        else:
            result += char.upper()
    return result


def tr_sorted(words):
    """
    Kelimeleri Türk alfabesine göre sıralar.
    Büyük/küçük harf farkı yoktur ve özel karakterler sıraya dahil edilir.
    """
    # Türk alfabesi karakterleri
    turkce_alphabet = "0123456789abcçdefgğhıijklmnoöpqrsştuüvwxyz"

    def normalize_word(word):
        """Kelimeyi küçük harfe çevirip, özel karakterlerin sırasını ayarlar."""
        # Harf ve sayılar için küçük harfe çevirme
        normalized = tr_lower(word)

        # Özel durum: kelimenin içindeki diğer karakterleri Unicode'ya göre sırala
        return normalized

    def key_for_sorting(word):
        """Sıralama için anahtar üretir."""
        normalized = normalize_word(word)
        result = []

        for char in normalized:
            if char in turkce_alphabet:
                # Türk alfabesindeki karakterlerin sırasını kullan
                index = turkce_alphabet.index(char)
                result.append(index)
            else:
                # Diğer tüm karakterler Unicode kodlarına göre sıralanır
                result.append(0x10000 + ord(char))  # Yeni bir sıra için yüksek sayı

        return tuple(result)

    # Sıralama işlemi (girdi listesi değişmeden kalır)
    sorted_words = sorted(words, key=key_for_sorting)

    return sorted_words"}
